impl Calculator {
    fn new() -> Self {
        Calculator { value: 0.0 }
    }

    /**
     * * @description 加法运算
     * ? @param num - 要相加的数字
     * ! @return &mut Self 返回自身引用以支持链式调用
     */
    fn add(&mut self, num: f64) -> &mut Self {
        self.value += num;
        self
    }

    /**
     * * @description 乘法运算
     * ? @param num - 要相乘的数字
     * ! @return &mut Self 返回自身引用以支持链式调用
     */
    fn multiply(&mut self, num: f64) -> &mut Self {
        self.value *= num;
        self
    }

    /**
     * * @description 获取计算结果
     * ! @return f64 当前计算值
     */
    fn result(&self) -> f64 {
        self.value
    }
}

