    func removeTask(at index: Int) {
        guard index < tasks.count else { return }
        let removed = tasks.remove(at: index)
        print("任务已删除: \\(removed)")
    }

    /**
     * * @description 列出所有任务
     * ! @return void
     */
    func listTasks() {
        for (index, task) in tasks.enumerated() {
            print("\\(index + 1). \\(task)")
        }
    }
}

